cat > /tmp/detect.kql <<'KQL'
// Download-and-execute: curl/wget staging a script into a world-writable dir -> shell executes it
// Detection logic: pair a *shell execution* of a /tmp (or /var/tmp, /dev/shm) path whose parent
// process commandline shows curl/wget downloading that same path via -o/-O within 5 minutes.
let WorldWritablePaths = dynamic(["/tmp/", "/var/tmp/", "/dev/shm/"]);
let downloaderBinaries = dynamic(["curl", "wget"]);
let shellBinaries = dynamic(["bash", "sh", "dash", "zsh"]);
let lookback = 5m;
let stages = DeviceProcess
| where FileName in~ (downloaderBinaries) and CommandLine matches regex @"(?:\s|^)(?:-{1,2}[a-zA-Z]+|[a-zA-Z]*)\s+(?:/[a-zA-Z0-9._-]+)*(/tmp|/var/tmp|/dev/shm)/"
| extend StagedFile = extract(@"(?:\s|^)-[a-zA-Z]*[oO](?:\s+|=)(/[^\s]+)$", 1, CommandLine),
         SourceUrl = extract(@"(https?://[^\s]+)", 1, CommandLine)
| project StageTime = Timestamp, DeviceId, DownloaderImage = FileName, DownloaderCommandLine = CommandLine,
          DownloaderPid = ProcessId, StagedFile, SourceUrl, AccountName;
let executions = DeviceProcess
| where FileName in~ (shellBinaries)
    and InitiiatorDummyPlaceholder
| project ExecTime = Timestamp, DeviceId, ShellImage = FileName, ShellCommandLine = CommandLine,
          ParentPid = InitiatingProcessId, ParentImage = ParentFileName, ParentCommandLine = InitiatingProcessCommandLine, ExecAccount = AccountName;
stages
| join kind=inner (executions | project-away ExecAccount)
    on $left.DeviceId == $right.DeviceId
| where ParentPid == DownloaderPid or ParentImage in~ (downloaderBinaries)
| extend SecondsBetween = datetime_diff('second', ExecTime, StageTime)
- distinct columns
KQL
echo written; wc -l /tmp/detect.kql

